//==============================================================================
// FB_INST_DIP1500
// Kamoer DIP1500 peristaltic pump, Modbus RTU, 32-bit low word first (CDAB)
// 1. INPUTS     : requests, control mode, command source, equipment feedback -> INTERN
// 2. PROCESSING : on INTERN only
// 3. OUTPUTS    : INTERN -> COM / IO / EXC
// Parameters    : pump configuration in PA (persistent), taken from the HMI in local HMI with "parameter write enable"
// Control mode  : local HMI (individual or global) > auto (functional units)
//==============================================================================

//------------------------------------------------------------------------------
// 1. INPUTS
//------------------------------------------------------------------------------
	//--- Control mode requests (HMI, global HMI local from UPI_LOCAL_HMI)
	INTERN.HMI_LOCAL_REQUEST := COM.HMI_INPUT_LOCAL_REQUEST;
	INTERN.HMI_AUTO_REQUEST  := COM.HMI_INPUT_AUTO_REQUEST;
	INTERN.GLOBAL_LOCAL_HMI  := EXC.UPI_INPUT_GLOBAL_LOCAL_HMI;

	//--- Control mode
	// Individual memory : set by the local request, reset by the auto request (auto wins if both)
	IF INTERN.HMI_LOCAL_REQUEST THEN
		INTERN.LOCAL_HMI_INDIVIDUAL := TRUE;
	END_IF
	IF INTERN.HMI_AUTO_REQUEST THEN
		INTERN.LOCAL_HMI_INDIVIDUAL := FALSE;
	END_IF

	// Resulting mode : HMI local (individual OR global), otherwise auto
	INTERN.LOCAL_HMI := INTERN.LOCAL_HMI_INDIVIDUAL OR INTERN.GLOBAL_LOCAL_HMI;
	INTERN.AUTO      := NOT INTERN.LOCAL_HMI;

	//--- Command source : local HMI > auto (UPI)
	IF INTERN.LOCAL_HMI THEN
		INTERN.CMD_RUN            := COM.HMI_INPUT_MOTOR_START_STOP;
		INTERN.CMD_CLOCKWISE      := COM.HMI_INPUT_MOTOR_DIRECTION;
		INTERN.CMD_VOLUME_MODE    := COM.HMI_INPUT_OPERATION_MODE;
		INTERN.CMD_SPEED          := COM.HMI_INPUT_MOTOR_SPEED.Real_value;
		INTERN.CMD_RUN_SETPOINT   := COM.HMI_INPUT_RUN_TIME_OR_VOLUME_SETPOINT.Real_value;
		INTERN.FLASH_SAVE_REQUEST := COM.HMI_INPUT_FLASH_SAVE;
		INTERN.PARAM_WRITE_ENABLE := COM.HMI_INPUT_PARAM_WRITE_ENABLE;
	ELSE
		// Auto : functional units (UPI), the configuration is never written in auto
		INTERN.CMD_RUN            := EXC.UPI_INPUT_RUN;
		INTERN.CMD_CLOCKWISE      := EXC.UPI_INPUT_CLOCKWISE;
		INTERN.CMD_VOLUME_MODE    := EXC.UPI_INPUT_VOLUME_MODE;
		INTERN.CMD_SPEED          := EXC.UPI_INPUT_SPEED;
		INTERN.CMD_RUN_SETPOINT   := EXC.UPI_INPUT_RUN_SETPOINT;
		INTERN.FLASH_SAVE_REQUEST := FALSE;
		INTERN.PARAM_WRITE_ENABLE := FALSE;
	END_IF

	//--- Parameters typed on the HMI
	INTERN.PARAM_MAX_MOTOR_SPEED         := COM.HMI_INPUT_MAX_MOTOR_SPEED.Real_value;
	INTERN.PARAM_CALIBRATION_COEFFICIENT := COM.HMI_INPUT_FLOW_RATE_OR_SPEED_CALIBRATION_COEFFICIENT.Real_value;
	INTERN.PARAM_FOOT_SWITCH_INPUT_MODE  := COM.HMI_INPUT_FOOT_SWITCH_INPUT_MODE;
	INTERN.PARAM_LIQUID_LEVEL_INPUT_MODE := COM.HMI_INPUT_LIQUID_LEVEL_INPUT_MODE;
	INTERN.PARAM_STATE_OUTPUT_MODE       := COM.HMI_INPUT_STATE_OUTPUT_MODE;
	INTERN.PARAM_COMMUNICATION_ADDRESS   := COM.HMI_INPUT_COMMUNICATION_ADDRESS;
	INTERN.PARAM_BAUD_RATE_INDEX         := COM.HMI_INPUT_BAUD_RATE_INDEX;

	//--- COM : feedback from the pump
	INTERN.FBK_FIRMWARE_VERSION := COM.COM_INPUT_FIRMWARE_VERSION;
	INTERN.FBK_HARDWARE_VERSION := COM.COM_INPUT_HARDWARE_VERSION;
	INTERN.FBK_TEMPERATURE      := COM.COM_INPUT_TEMPERATURE;
	INTERN.FBK_LEVEL_ALARM      := COM.COM_INPUT_LEVEL_ALARM;
	INTERN.FBK_DIGITAL_OUTPUT   := COM.COM_INPUT_DIGITAL_OUTPUT;

	// Run counters : REAL (ml) in volume mode, UDINT (ms) in time mode
	IF INTERN.CMD_VOLUME_MODE THEN
		INTERN.FBK_RUN_ACTUAL := COM.COM_INPUT_RUN_ACTUAL.Real_value;
		INTERN.FBK_RUN_TOTAL  := COM.COM_INPUT_RUN_TOTAL.Real_value;
	ELSE
		INTERN.FBK_RUN_ACTUAL := UDINT_TO_REAL(SHL(WORD_TO_UDINT(COM.COM_INPUT_RUN_ACTUAL.Word_value[1]), 16) OR WORD_TO_UDINT(COM.COM_INPUT_RUN_ACTUAL.Word_value[0]));
		INTERN.FBK_RUN_TOTAL  := UDINT_TO_REAL(SHL(WORD_TO_UDINT(COM.COM_INPUT_RUN_TOTAL.Word_value[1]), 16) OR WORD_TO_UDINT(COM.COM_INPUT_RUN_TOTAL.Word_value[0]));
	END_IF


//------------------------------------------------------------------------------
// 2. PROCESSING
//------------------------------------------------------------------------------
	//--- Parameters : the HMI values are saved in PA while "parameter write enable" is on and they are valid
	// PA is persistent : it keeps its value after a restart or a download. Default = declaration value.
	INTERN.PARAM_VALID := (WORD_TO_UINT(INTERN.PARAM_COMMUNICATION_ADDRESS) >= 1) AND (WORD_TO_UINT(INTERN.PARAM_COMMUNICATION_ADDRESS) <= 31)
	                      AND (WORD_TO_UINT(INTERN.PARAM_BAUD_RATE_INDEX) <= 7)
	                      AND (INTERN.PARAM_MAX_MOTOR_SPEED > 0.0) AND (INTERN.PARAM_CALIBRATION_COEFFICIENT > 0.0);

	IF INTERN.PARAM_WRITE_ENABLE AND INTERN.PARAM_VALID THEN
		PA.MAX_MOTOR_SPEED         := INTERN.PARAM_MAX_MOTOR_SPEED;
		PA.CALIBRATION_COEFFICIENT := INTERN.PARAM_CALIBRATION_COEFFICIENT;
		PA.FOOT_SWITCH_INPUT_MODE  := INTERN.PARAM_FOOT_SWITCH_INPUT_MODE;
		PA.LIQUID_LEVEL_INPUT_MODE := INTERN.PARAM_LIQUID_LEVEL_INPUT_MODE;
		PA.STATE_OUTPUT_MODE       := INTERN.PARAM_STATE_OUTPUT_MODE;
		PA.COMMUNICATION_ADDRESS   := INTERN.PARAM_COMMUNICATION_ADDRESS;
		PA.BAUD_RATE_INDEX         := INTERN.PARAM_BAUD_RATE_INDEX;
	END_IF

	//--- Flash save : 1 s pulse on the rising edge of the request
	TP_FLASH(IN := INTERN.FLASH_SAVE_REQUEST, PT := T#1S);
	INTERN.CMD_SAVE_FLASH := TP_FLASH.Q;

	//--- Run setpoint in time mode : integer (ms)
	INTERN.RUN_SETPOINT_MS := REAL_TO_UDINT(MAX(INTERN.CMD_RUN_SETPOINT, 0.0));

	//--- Write triggers (the Modbus write channels are sent on a rising edge)
	// Square wave 500 ms : each rising edge = one write request
	TON_PULSE(IN := NOT TON_PULSE.Q, PT := T#250MS);
	IF TON_PULSE.Q THEN
		INTERN.PULSE_500MS := NOT INTERN.PULSE_500MS;
	END_IF

	// Command trigger : 3 s of edges after any command change
	INTERN.CMD_CHANGED := (INTERN.CMD_RUN <> INTERN.PREV_RUN) OR (INTERN.CMD_CLOCKWISE <> INTERN.PREV_CLOCKWISE)
	                      OR (INTERN.CMD_VOLUME_MODE <> INTERN.PREV_VOLUME_MODE) OR (INTERN.CMD_SAVE_FLASH <> INTERN.PREV_SAVE_FLASH)
	                      OR (INTERN.CMD_SPEED <> INTERN.PREV_SPEED) OR (PA.MAX_MOTOR_SPEED <> INTERN.PREV_MAX_SPEED)
	                      OR (INTERN.CMD_RUN_SETPOINT <> INTERN.PREV_RUN_SETPOINT);
	INTERN.PREV_RUN          := INTERN.CMD_RUN;
	INTERN.PREV_CLOCKWISE    := INTERN.CMD_CLOCKWISE;
	INTERN.PREV_VOLUME_MODE  := INTERN.CMD_VOLUME_MODE;
	INTERN.PREV_SAVE_FLASH   := INTERN.CMD_SAVE_FLASH;
	INTERN.PREV_SPEED        := INTERN.CMD_SPEED;
	INTERN.PREV_MAX_SPEED    := PA.MAX_MOTOR_SPEED;
	INTERN.PREV_RUN_SETPOINT := INTERN.CMD_RUN_SETPOINT;

	TOF_CMD_WINDOW(IN := INTERN.CMD_CHANGED, PT := T#3S);
	INTERN.CMD_TRIGGER := TOF_CMD_WINDOW.Q AND (PA.MAX_MOTOR_SPEED > 0.0) AND INTERN.PULSE_500MS;

	// Configuration trigger : while "parameter write enable" is on and the HMI parameters are valid
	INTERN.CONFIG_TRIGGER := INTERN.PARAM_WRITE_ENABLE AND INTERN.PARAM_VALID AND INTERN.PULSE_500MS;


//------------------------------------------------------------------------------
// 3. OUTPUTS
//------------------------------------------------------------------------------
	//--- COM : control mode status to HMI
	COM.HMI_OUTPUT_LOCAL_ACTIVE := INTERN.LOCAL_HMI;

	//--- COM : Modbus RTU commands (sent on the command trigger)
	COM.COM_OUTPUT_RUN                        := INTERN.CMD_RUN;
	COM.COM_OUTPUT_CLOCKWISE                  := INTERN.CMD_CLOCKWISE;
	COM.COM_OUTPUT_SAVE_FLASH                 := INTERN.CMD_SAVE_FLASH;
	COM.COM_OUTPUT_VOLUME_MODE                := INTERN.CMD_VOLUME_MODE;
	COM.COM_OUTPUT_SPEED.Real_value           := INTERN.CMD_SPEED;
	COM.COM_OUTPUT_MAX_MOTOR_SPEED.Real_value := PA.MAX_MOTOR_SPEED;

	// Run setpoint : REAL (ml) in volume mode, UDINT (ms) in time mode
	IF INTERN.CMD_VOLUME_MODE THEN
		COM.COM_OUTPUT_RUN_SETPOINT.Real_value := INTERN.CMD_RUN_SETPOINT;
	ELSE
		COM.COM_OUTPUT_RUN_SETPOINT.Word_value[0] := UDINT_TO_WORD(INTERN.RUN_SETPOINT_MS);
		COM.COM_OUTPUT_RUN_SETPOINT.Word_value[1] := UDINT_TO_WORD(SHR(INTERN.RUN_SETPOINT_MS, 16));
	END_IF

	//--- COM : Modbus RTU configuration, always from PA (sent on the configuration trigger)
	COM.COM_OUTPUT_CALIBRATION_COEFFICIENT.Real_value := PA.CALIBRATION_COEFFICIENT;
	COM.COM_OUTPUT_FOOT_SWITCH_INPUT_MODE             := PA.FOOT_SWITCH_INPUT_MODE;
	COM.COM_OUTPUT_LIQUID_LEVEL_INPUT_MODE            := PA.LIQUID_LEVEL_INPUT_MODE;
	COM.COM_OUTPUT_STATE_OUTPUT_MODE                  := PA.STATE_OUTPUT_MODE;
	COM.COM_OUTPUT_COMMUNICATION_ADDRESS              := PA.COMMUNICATION_ADDRESS;
	COM.COM_OUTPUT_BAUD_RATE_INDEX                    := PA.BAUD_RATE_INDEX;

	//--- COM : Modbus RTU write triggers
	COM.COM_OUTPUT_CMD_TRIGGER    := INTERN.CMD_TRIGGER;
	COM.COM_OUTPUT_CONFIG_TRIGGER := INTERN.CONFIG_TRIGGER;

	//--- COM : feedback to HMI
	COM.HMI_OUTPUT_FIRMWARE_VERSION                          := INTERN.FBK_FIRMWARE_VERSION;
	COM.HMI_OUTPUT_HARDWARE_VERSION                          := INTERN.FBK_HARDWARE_VERSION;
	COM.HMI_OUTPUT_TEMPERATURE                               := INTERN.FBK_TEMPERATURE;
	COM.HMI_OUTPUT_FLOAT_LEVEL_ALARM                         := INTERN.FBK_LEVEL_ALARM;
	COM.HMI_OUTPUT_DIGITAL_OUTPUT_VALUE                      := INTERN.FBK_DIGITAL_OUTPUT;
	COM.HMI_OUTPUT_REAL_TIME_RUN_TIME_OR_VOLUME.Real_value   := INTERN.FBK_RUN_ACTUAL;
	COM.HMI_OUTPUT_ACCUMULATED_RUN_TIME_OR_VOLUME.Real_value := INTERN.FBK_RUN_TOTAL;
